from PIL import Image
import numpy as np

def analyze_image_detail(image_path):
    # Open and analyze the image
    img = Image.open(image_path)
    img = img.convert('RGB')
    width, height = img.size

    print(f"Analyzing image in detail ({width}x{height})")

    # Create a pixel map
    pixels = img.load()

    # Look for text-like patterns
    text_candidates = []

    # Sample some areas for detailed analysis
    for y in range(0, height, 10):
        for x in range(0, width, 10):
            pixel = pixels[x, y]
            # Check for high contrast areas that might contain text
            if sum(pixel) > 600 or sum(pixel) < 100:
                neighbors = []
                for dy in [-1, 0, 1]:
                    for dx in [-1, 0, 1]:
                        if 0 <= x+dx < width and 0 <= y+dy < height:
                            neighbors.append(pixels[x+dx, y+dy])

                # If there's significant contrast with neighbors, might be text
                for neighbor in neighbors:
                    if abs(sum(pixel) - sum(neighbor)) > 200:
                        text_candidates.append((x, y))
                        break

    print(f"\nFound {len(text_candidates)} potential text locations")

    # Look for repeating patterns
    print("\nAnalyzing patterns...")

    # Check borders and corners specifically
    borders = []
    for x in range(width):
        borders.append(pixels[x, 0])
        borders.append(pixels[x, height-1])
    for y in range(height):
        borders.append(pixels[0, y])
        borders.append(pixels[width-1, y])

    print("\nBorder analysis complete")

    # Look for isolated text or patterns
    isolated = []
    for y in range(10, height-10, 20):
        for x in range(10, width-10, 20):
            surrounding = []
            center = pixels[x, y]
            for dy in range(-5, 6):
                for dx in range(-5, 6):
                    if 0 <= x+dx < width and 0 <= y+dy < height:
                        surrounding.append(pixels[x+dx, y+dy])

            # If center is significantly different from surroundings
            if abs(sum(center) - sum([sum(p) for p in surrounding])/len(surrounding)) > 100:
                isolated.append((x, y))

    print(f"\nFound {len(isolated)} isolated features")

