from PIL import Image
import numpy as np

def detect_text(img_path):
    # Open image and convert to grayscale array
    img = Image.open(img_path)
    gray = img.convert('L')
    data = np.array(gray)

    height, width = data.shape

    # Function to detect if a region might contain text
    def is_text_region(region):
        # Look for high contrast areas
        mean = np.mean(region)
        std = np.std(region)
        return std > 30 and (mean > 50 and mean < 200)

    # Scan image in blocks
    block_size = 50
    for y in range(0, height-block_size, block_size//2):
        for x in range(0, width-block_size, block_size//2):
            block = data[y:y+block_size, x:x+block_size]
            if is_text_region(block):
                print(f"Potential text region at ({x}, {y})")
                # Print ASCII representation of block
                text_block = ''
                for row in block:
                    line = ''
                    for pixel in row:
                        if pixel < 100:
                            line += '#'
                        else:
                            line += ' '
                    text_block += line + '\n'
                print(text_block)

